import {dubaiDate,prettyDate,message,phoneList,waUrl,normalizeMeetingEdit} from './core.mjs';
import {validateReport,monthlyReport,reportCsv,dateRange} from './reporting.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy=async text=>{await navigator.clipboard.writeText(text)};
const field=(label,name,value='',type='text',required=false)=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;
const area=(label,name,value='',required=false)=>`<label class="field">${label}<textarea name="${name}" rows="3" maxlength="6000" ${required?'required':''}>${esc(value)}</textarea></label>`;
function reportFields(r={}){return `${field('Your name','organizerName',r.organizerName||'','text',true)}<label class="field">Meeting outcome<select name="status">${['held','cancelled','postponed'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></label><div class="editor-grid">${field('Number who participated','participants',r.participants??'','number')}<label class="field">Teaching rating<select name="teachingRating"><option value="">Choose 1–5</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${r.teachingRating===n?'selected':''}>${n} · ${['Needs improvement','Fair','Good','Very good','Excellent'][n-1]}</option>`).join('')}</select></label></div>${area('How was the teaching?','teachingFeedback',r.teachingFeedback||'')}${area('Comments / follow-up','comments',r.comments||'')}<p class="muted">For a held gubae, enter the participant count, teaching rating, and feedback. Cancelled or postponed gubaes do not contribute to attendance averages.</p>`}
export function createWorkspace(bridge){
 let apiBase='',user=null,auth=null,records=[],teachers=[],reports=[],etag='',mode='local',syncError='',pending=null,timer,chain=Promise.resolve(),polling=false,syncing=false;
 const localKey='gubae-private-workspace-v2';let local={teachers:[],reports:[],assignments:{},teacherSent:{}};try{local={...local,...JSON.parse(localStorage.getItem(localKey)||'{}')}}catch{}
 let month=dubaiDate().slice(0,7),custom=false,from='',to='';
 const cloud=()=>mode==='cloud';
 const notice=text=>{$('#syncText').textContent=text;$('.local-note').textContent=text};
 const error=e=>{bridge.toast(e.message||'Could not complete this action.')};
 const persistLocal=()=>{localStorage.setItem(localKey,JSON.stringify(local))};
 function currentTeachers(){return cloud()?teachers:local.teachers}
 function currentReports(){return cloud()?reports:local.reports}
 function assignment(id){return cloud()?records.find(m=>m.id===id)?.teacherId:local.assignments[id]}
 async function request(path,method='GET',body,headers={}){if(!user)throw Error('Sign in to use the shared workspace.');const response=await fetch(apiBase+path,{method,headers:{Authorization:'Bearer '+await user.getIdToken(),...(body?{'Content-Type':'application/json'}:{}),...headers},body:body?JSON.stringify(body):undefined});if(response.status===304)return null;const data=response.status===204?null:await response.json();if(!response.ok)throw Object.assign(Error(data?.error||'The server could not complete the request.'),{status:response.status});return{data,tag:response.headers.get('ETag')}}
 function applyRecords(){const next={recipients:{},sent:{},meetingEdits:{}};for(const m of records){next.recipients[m.id]=m.recipient||'';next.meetingEdits[m.id]=normalizeMeetingEdit(m,m);for(const kind of ['poster','link'])if(m.sent?.[kind])next.sent[m.id+':'+kind]=m.sent[kind]}bridge.setState(next);bridge.render()}
 async function pull(force=false){if(!cloud()||pending||polling||syncing||(!force&&(document.querySelector('dialog[open]')||document.activeElement?.matches('input,textarea,select'))))return;polling=true;try{const result=await request('/api/state','GET',null,!force&&etag?{'If-None-Match':etag}:{});if(result){records=result.data.meetings;teachers=result.data.teachers;reports=result.data.reports;etag=result.tag;applyRecords()}notice('Cloud synced · '+user.email)}catch(e){notice('Sync unavailable · changes need attention');error(e)}finally{polling=false}}
 function accept(record){records=records.map(m=>m.id===record.id?record:m);etag=''}
 async function syncSnapshot(snapshot){for(let m of [...records]){const desired=normalizeMeetingEdit(m,snapshot.meetingEdits[m.id]||bridge.base().find(b=>b.id===m.id));const patch={};if(JSON.stringify(desired)!==JSON.stringify(normalizeMeetingEdit(m,m)))patch.details=desired;if((snapshot.recipients[m.id]||'')!==(m.recipient||''))patch.recipient=snapshot.recipients[m.id]||'';if(Object.keys(patch).length){const r=await request('/api/meetings/'+m.id,'PATCH',{revision:m.revision,...patch});m=r.data;accept(m)}for(const kind of ['poster','link']){const wanted=!!snapshot.sent[m.id+':'+kind];if(wanted!==!!m.sent?.[kind]){const r=await request(`/api/meetings/${m.id}/status/${kind}`,'PUT',{revision:m.revision,sent:wanted});m=r.data;accept(m)}}}}
 async function flush(){clearTimeout(timer);await chain;if(!pending)return;if(syncError)throw Error(syncError);const snapshot=pending;pending=null;notice('Saving to cloud…');syncing=true;chain=syncSnapshot(snapshot);try{await chain;syncing=false;notice(pending?'Saving to cloud…':'Cloud synced · '+user.email);if(pending)return flush()}catch(e){syncing=false;pending=structuredClone(bridge.state());syncError=e.status===409?'Another device changed this record. Discard this device’s pending edits, refresh, and apply your change again.':'Cloud save was not confirmed. Your pending changes remain open on this device. Retry before closing.';notice(syncError);chain=Promise.resolve();throw Error(syncError)}}
 const persist=state=>{if(!cloud())return false;pending=structuredClone(state);syncError='';notice('Unsynced changes · saving…');clearTimeout(timer);timer=setTimeout(()=>flush().catch(error),650);return true};
 async function mutate(path,method,body){await flush();const r=await request(path,method,body);await pull(true);return r?.data}
 async function action(run){try{await run()}catch(e){error(e)}}
 function renderGate(){return`<div class="notice">${cloud()?'Shared workspace · signed in as '+esc(user.email):'On this device. Connect the backend in Setup and sign in to share data across mobile and PC.'}</div>`}
 function teachersView(){return`<div class="workspace"><div class="section-top"><div><h2 class="section-title">Teachers & Zoom invitations</h2><p class="section-subtitle">Private contacts. Teacher names stay out of announcement messages.</p></div><button class="primary" id="newTeacher">Add teacher</button></div><div class="setup">${renderGate()}<div class="teacher-list">${currentTeachers().map(t=>`<article class="contact-card"><strong>${esc(t.name)}${t.archived?' · archived':''}</strong><p>${esc(t.phone)}${t.email?' · '+esc(t.email):''}</p><p>${esc(t.notes)}</p><button class="secondary" data-teacher-edit="${t.id}">Edit contact</button></article>`).join('')||'<p>No teacher contacts yet. Add a contact, then assign them to a gubae below.</p>'}</div></div>${bridge.meetings().map(m=>{const assigned=assignment(m.id),t=currentTeachers().find(t=>t.id===assigned),done=cloud()?records.find(r=>r.id===m.id)?.sent?.teacher:local.teacherSent[m.id];return`<div class="recipient-row"><div><h3 lang="am">${esc(m.topic)}</h3><small>${prettyDate(m.date)} · Dubai</small></div><div class="field"><label for="teacher-${m.id}">Assigned teacher</label><select id="teacher-${m.id}" data-assignment="${m.id}"><option value="">Unassigned</option>${currentTeachers().filter(t=>!t.archived||t.id===assigned).map(t=>`<option value="${t.id}" ${t.id===assigned?'selected':''}>${esc(t.name)}</option>`).join('')}</select>${t?`<button class="prepare" data-teacher-send="${m.id}">Open Zoom invitation ↗</button><button class="secondary" data-teacher-status="${m.id}">${done?'✓ Sent · undo':'Mark sent to teacher'}</button>`:''}</div></div>`}).join('')}</div>`}
 function teacherEditor(id){const t=currentTeachers().find(t=>t.id===id)||{};showModal('Private teacher contact',`<form id="teacherForm" class="form-stack">${field('Teacher name (private)','name',t.name||'','text',true)}${field('WhatsApp number · include country code','phone',t.phone||'','tel',true)}${field('Email (optional)','email',t.email||'','email')}${area('Notes (private)','notes',t.notes||'')}<label><input name="archived" type="checkbox" ${t.archived?'checked':''}> Archive contact</label><button class="primary">Save contact</button><p role="alert" id="formError"></p></form>`);$('#teacherForm').onsubmit=e=>{e.preventDefault();submitForm(e.target,async()=>{const data=Object.fromEntries(new FormData(e.target));data.archived=e.target.elements.archived.checked;if(cloud())await mutate('/api/teachers'+(id?'/'+id:''),id?'PATCH':'POST',{...data,...(id?{revision:t.revision}:{})});else{const {validPhoneList}=await import('./core.mjs');if(!validPhoneList(data.phone))throw Error('Enter a valid international phone number.');const next={...t,...data,id:id||crypto.randomUUID()};local.teachers=id?local.teachers.map(v=>v.id===id?next:v):[...local.teachers,next];persistLocal()}$('#workspaceDialog').close();bridge.render()})}}
 function reportsView(){return`<div class="workspace"><div class="section-top"><div><h2 class="section-title">Gubae day reports</h2><p class="section-subtitle">Attendance, teaching feedback, and comments from each organizer.</p></div></div><div class="setup">${renderGate()}<p>Reporting opens on the meeting day in Dubai. Each organizer link allows access to one gubae’s report and expires 45 days after its date.</p></div>${bridge.meetings().sort((a,b)=>a.date.localeCompare(b.date)).map(m=>{const r=currentReports().find(r=>(r.meetingId||r.id)===m.id);return`<div class="report-row"><div><h3 lang="am">${esc(m.topic)}</h3><small>${prettyDate(m.date)} · ${r?'Submitted · '+esc(r.status):m.date>dubaiDate()?'Not yet due':'Report missing'}</small></div><div class="button-row"><button class="secondary" data-report-edit="${m.id}" ${m.date>dubaiDate()?'disabled':''}>${r?'Edit report':'Enter report'}</button>${cloud()?`<button class="prepare" data-report-link="${m.id}">Organizer link ↗</button>`:''}</div></div>`}).join('')}</div>`}
 function editReport(id){const m=bridge.meetings().find(m=>m.id===id),r=currentReports().find(r=>(r.meetingId||r.id)===id)||{};showModal('Gubae report',`<h2 lang="am" class="detail-title">${esc(m.topic)}</h2><p>${prettyDate(m.date)} · Dubai</p><form class="form-stack" id="reportForm">${reportFields(r)}<button class="primary">Save report</button><p role="alert" id="formError"></p></form>`);$('#reportForm').onsubmit=e=>{e.preventDefault();submitForm(e.target,async()=>{if(m.date>dubaiDate())throw Error('Reporting opens on the gubae day.');const data=validateReport(Object.fromEntries(new FormData(e.target)));if(cloud())await mutate('/api/meetings/'+id+'/report','PUT',{...data,revision:r.revision||0});else{const record={...data,id,meetingId:id,updatedAt:new Date().toISOString()};local.reports=[...local.reports.filter(v=>v.meetingId!==id),record];persistLocal()}$('#workspaceDialog').close();bridge.render();bridge.toast('Report saved.')})}}
 function monthlyView(){const range=custom?{from,to}:{month};let report;try{report=monthlyReport(bridge.meetings(),currentReports(),range,dubaiDate())}catch{}const s=report?.summary;return`<div class="workspace"><div class="section-top"><div><h2 class="section-title">Monthly service report</h2><p class="section-subtitle">Generate a month or any custom period, including the whole gubae program.</p></div></div><div class="setup report-setup">${renderGate()}<div class="button-row"><label class="field">Month<input id="reportMonth" type="month" value="${month}"></label><button class="secondary" id="fullProgram">Full program</button><button class="secondary" id="customRange">${custom?'Use month':'Custom dates'}</button></div>${custom?`<div class="button-row">${field('From','from',from,'date')}${field('Through','to',to,'date')}</div>`:''}${report?`<div class="report-summary">${[['Scheduled',s.scheduled],['Reports submitted',s.submitted],['Missing reports',s.missing],['Total attendances',s.totalParticipants],['Average participation',s.averageParticipants??'—'],['Teaching rating / 5',s.averageTeachingRating??'—']].map(([l,v])=>`<article><span>${l}</span><strong>${v}</strong></article>`).join('')}</div><p class="muted">${prettyDate(report.from)} – ${prettyDate(report.to)} · ${s.held} held, ${s.cancelled} cancelled, ${s.postponed} postponed · ${s.upcoming} upcoming. Attendance totals count visits, not unique people. Averages use submitted reports for held gubaes.</p><div class="button-row"><button class="primary" id="exportReport">Download CSV</button><button class="secondary" id="printReport">Print / Save PDF</button></div>`:'<p class="bad">Choose valid dates (up to one year).</p>'}</div>${report?reportTable(report):''}</div>`}
 function reportTable(r){return`<div class="report-table-wrap" id="printArea"><h2 class="print-only">Gubae monthly report · ${esc(r.from)} – ${esc(r.to)}</h2><p class="print-only">${r.summary.submitted} reports · ${r.summary.missing} missing · ${r.summary.totalParticipants} attendances · teaching rating ${r.summary.averageTeachingRating??'—'}/5</p><table class="report-table"><thead><tr><th>Gubae / date</th><th>Status</th><th>Participants</th><th>Teaching</th><th>Comments</th></tr></thead><tbody>${r.rows.map(v=>`<tr><td><strong lang="am">${esc(v.topic)}</strong><small>${esc(v.date)}</small>${v.report?`<small>Organizer: ${esc(v.report.organizerName)}</small>`:''}</td><td>${esc(v.reportStatus)}${v.report?'<small>'+esc(v.report.status)+'</small>':''}</td><td>${v.report?.status==='held'?v.report.participants:'—'}</td><td>${v.report?.teachingRating??'—'}<p>${esc(v.report?.teachingFeedback)}</p></td><td>${esc(v.report?.comments)}</td></tr>`).join('')||'<tr><td colspan="5">No gubaes in this period.</td></tr>'}</tbody></table></div>`}
 function setupView(){return `<section class="cloud-setup setup"><h3>Shared workspace</h3><p>Use the same administrator Google account on your phone and PC. Cloud records are accessible only after sign-in.</p><label class="field">Render backend URL<input type="url" id="apiBase" value="${esc(apiBase)}" placeholder="https://your-service.onrender.com"></label><div class="button-row"><button class="primary" id="connectBackend">Connect backend</button>${auth?`<button class="secondary" id="signIn">${user?'Sign out':'Sign in with Google'}</button>`:''}${cloud()?'<button class="secondary" id="refreshCloud">Refresh cloud</button><button class="secondary" id="migrateLocal">Import this device’s original setup</button><button class="secondary" id="cloudBackup">Export cloud records</button>':''}</div><p class="muted">${apiBase?'Cloud connection configured.':'Backend has not been deployed yet. The app currently saves on this device.'} Original posters are shared with all devices; custom poster replacements remain on the device where you attach them. Sending still finishes in WhatsApp.</p></section>`}
 function showModal(title,html){$('#workspaceDialogTitle').textContent=title;$('#workspaceDialogBody').innerHTML=html;$('#workspaceDialog').showModal()}
 async function submitForm(form,fn){const button=form.querySelector('button[type="submit"],button.primary');button.disabled=true;try{await fn()}catch(e){$('#formError').textContent=e.message}finally{button.disabled=false}}
 function bind(){
 $('#newTeacher')?.addEventListener('click',()=>teacherEditor());document.querySelectorAll('[data-teacher-edit]').forEach(b=>b.onclick=()=>teacherEditor(b.dataset.teacherEdit));
 document.querySelectorAll('[data-assignment]').forEach(b=>b.onchange=()=>action(async()=>{const id=b.dataset.assignment;if(cloud()){await flush();const m=records.find(m=>m.id===id);await mutate('/api/meetings/'+id,'PATCH',{revision:m.revision,teacherId:b.value||null})}else{local.assignments[id]=b.value;persistLocal();bridge.render()}}));
 document.querySelectorAll('[data-teacher-send]').forEach(b=>b.onclick=()=>action(async()=>{const m=bridge.meetings().find(m=>m.id===b.dataset.teacherSend),t=currentTeachers().find(t=>t.id===assignment(m.id)),phones=phoneList(t.phone);if(phones.length===1)window.open(waUrl(phones[0],message(m)),'_blank','noopener,noreferrer');else showModal('Choose teacher’s number',`<p>Select the intended private chat.</p>${phones.map(p=>`<p><a target="_blank" rel="noopener noreferrer" href="${esc(waUrl(p,message(m)))}">${esc(p)} ↗</a></p>`).join('')}`)}));
 document.querySelectorAll('[data-teacher-status]').forEach(b=>b.onclick=()=>action(async()=>{const id=b.dataset.teacherStatus;if(cloud()){await flush();const m=records.find(m=>m.id===id);await mutate(`/api/meetings/${id}/status/teacher`,'PUT',{revision:m.revision,sent:!m.sent?.teacher})}else{local.teacherSent[id]=!local.teacherSent[id];persistLocal();bridge.render()}}));
 document.querySelectorAll('[data-report-edit]').forEach(b=>b.onclick=()=>editReport(b.dataset.reportEdit));
 document.querySelectorAll('[data-report-link]').forEach(b=>b.onclick=()=>{const id=b.dataset.reportLink;showModal('Organizer report link',`<p>A new link replaces the previous link for this gubae. Anyone holding it can view and edit only this report.</p><div class="button-row"><button class="primary" id="generateLink">Create / replace link</button><button class="secondary" id="revokeLink">Revoke access</button></div><div id="linkResult"></div>`);$('#generateLink').onclick=()=>action(async()=>{const result=await mutate('/api/meetings/'+id+'/report-link','POST',{});$('#linkResult').innerHTML=`<p>Expires ${esc(result.expiresAt.slice(0,10))}</p><label class="field">Organizer link<input readonly id="organizerLink" value="${esc(result.url)}"></label><button class="secondary" id="copyOrganizer">Copy organizer link</button>`;$('#copyOrganizer').onclick=()=>action(async()=>{await copy(result.url);bridge.toast('Organizer link copied.')})});$('#revokeLink').onclick=()=>action(async()=>{await mutate('/api/meetings/'+id+'/report-link','DELETE');$('#linkResult').textContent='Organizer access revoked.'})});
 $('#reportMonth')?.addEventListener('change',e=>{month=e.target.value;custom=false;bridge.render()});$('#fullProgram')?.addEventListener('click',()=>{const dates=bridge.meetings().map(m=>m.date).sort();from=dates[0];to=dates.at(-1);custom=true;bridge.render()});$('#customRange')?.addEventListener('click',()=>{if(!from){const r=dateRange({month});from=r.from;to=r.to}custom=!custom;bridge.render()});for(const name of ['from','to'])document.querySelector(`.report-setup [name="${name}"]`)?.addEventListener('change',e=>{if(name==='from')from=e.target.value;else to=e.target.value;bridge.render()});
 $('#exportReport')?.addEventListener('click',()=>{const report=monthlyReport(bridge.meetings(),currentReports(),custom?{from,to}:{month},dubaiDate());bridge.download(new Blob([reportCsv(report)],{type:'text/csv;charset=utf-8'}),`gubae-report-${report.from}-${report.to}.csv`)});$('#printReport')?.addEventListener('click',()=>window.print());
 $('#connectBackend')?.addEventListener('click',()=>action(async()=>{const url=new URL($('#apiBase').value);if(url.protocol!=='https:'&&url.hostname!=='localhost')throw Error('Use an HTTPS backend URL.');localStorage.setItem('gubae-api-base',url.origin);location.reload()}));$('#signIn')?.addEventListener('click',()=>action(async()=>{if(user){if(pending)await flush();await auth.signOut();location.reload()}else await auth.signIn()}));$('#refreshCloud')?.addEventListener('click',()=>action(async()=>{await flush();await pull(true)}));$('#migrateLocal')?.addEventListener('click',()=>action(async()=>{const data=JSON.parse(localStorage.getItem('gubae-announcements-v1')||'{}');const result=await mutate('/api/import','POST',{format:'gubae-v1',...data});bridge.toast(result.message)}));$('#cloudBackup')?.addEventListener('click',()=>action(async()=>{await flush();const result=await request('/api/state');bridge.download(new Blob([JSON.stringify({format:'gubae-cloud-v2',exportedAt:new Date().toISOString(),...result.data})],{type:'application/json'}),'gubae-cloud-backup-'+dubaiDate()+'.json')}));
 }
 function afterRender(){const container=$('#content');if(bridge.view()==='settings'){container.insertAdjacentHTML('afterbegin',setupView());if(cloud()){container.querySelector('.setup:not(.cloud-setup)')?.insertAdjacentHTML('afterbegin','<div class="notice">Cloud mode is active. Recipients, edits, sent status, teacher contacts, and reports sync through the backend. Export cloud records above for a complete cloud snapshot.</div>')}}if(cloud()){for(const el of container.querySelectorAll('.notice,.muted,.section-subtitle,.field-hint')){el.innerHTML=el.innerHTML.replaceAll('Numbers are stored only in this browser.','Numbers sync to your private cloud workspace.').replaceAll('This site does not synchronize between devices.','Cloud records sync after confirmed saves.').replaceAll('A simple frontend workspace, with your setup saved on your device.','Your workspace, connected across devices.')}}bind()}
 async function start(){
 const bar=document.createElement('div');bar.className='sync-bar';bar.innerHTML='<span id="syncText" role="status">On this device · cloud not connected</span><div class="button-row"><button class="secondary" id="retrySync">Retry sync</button><button class="secondary" id="discardSync">Discard pending / refresh</button><button class="secondary" id="openSetup">Cloud setup</button></div>';document.querySelector('header').after(bar);$('#openSetup').onclick=()=>bridge.navigate('settings');$('#retrySync').onclick=()=>action(async()=>{syncError='';await flush();await pull(true)});$('#discardSync').onclick=()=>action(async()=>{if(!cloud())return;pending=null;syncError='';await pull(true)});
 window.addEventListener('beforeunload',e=>{if(pending||syncing){e.preventDefault();e.returnValue=''}});
 const dialog=document.createElement('dialog');dialog.id='workspaceDialog';dialog.innerHTML='<div class="dialog-top"><span id="workspaceDialogTitle"></span><button class="icon-button" id="closeWorkspace" aria-label="Close form">×</button></div><div id="workspaceDialogBody"></div>';document.body.append(dialog);$('#closeWorkspace').onclick=()=>dialog.close();
 if(new URLSearchParams(location.search).has('report')){await organizerPage();return}
 try{const config=await fetch('./cloud-config.json').then(r=>r.json());apiBase=localStorage.getItem('gubae-api-base')||config.apiBase||'';if(apiBase){const url=new URL(apiBase);if(url.protocol!=='https:'&&url.hostname!=='localhost')throw Error('The backend URL must use HTTPS.');apiBase=url.origin;notice('Connecting to shared workspace…');const r=await fetch(apiBase+'/api/config');if(!r.ok)throw Error('Backend configuration could not load.');const cfg=await r.json();const {connectAuth}=await import('./firebase-auth.mjs');auth=await connectAuth(cfg.firebase,async next=>{user=next;if(user){mode='connecting';notice('Loading shared records…');try{const result=await request('/api/state');records=result.data.meetings;teachers=result.data.teachers;reports=result.data.reports;etag=result.tag;mode='cloud';applyRecords();notice('Cloud synced · '+user.email)}catch(e){mode='local';notice('Cloud sign-in failed · using this device');error(e)}}else{mode='local';notice('On this device · sign in for cloud sync')}bridge.render()});setInterval(()=>pull(),60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)pull()})}}catch(e){notice('Cloud unavailable · using this device');error(e)}bridge.render()
 }
 async function organizerPage(){document.querySelector('.app').hidden=true;const id=new URLSearchParams(location.search).get('report'),fragment=new URLSearchParams(location.hash.slice(1)),token=fragment.get('token');let base=fragment.get('api');const root=document.createElement('main');root.className='organizer-page';document.body.append(root);root.innerHTML='<h1>Gubae day report</h1><p>Loading your report…</p>';try{const url=new URL(base);if(url.protocol!=='https:'&&url.hostname!=='localhost')throw Error('Invalid report backend.');base=url.origin;if(!/^[A-Za-z0-9_-]+$/.test(id)||!/^gbr_[A-Za-z0-9_-]{43}$/.test(token||''))throw Error('The report link is incomplete. Ask for a new link.');const call=async(method,body)=>{const r=await fetch(base+'/api/public/report/'+id,{method,headers:{Authorization:'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw Error(data.error||'Could not load report.');return data};let data=await call('GET');function draw(){root.innerHTML=`<a class="brand" href="./">✣ Gubae</a><h1 lang="am">${esc(data.meeting.topic)}</h1><p>${prettyDate(data.meeting.date)} · Dubai</p>${!data.canSubmit?'<div class="notice">Reporting opens on the gubae day. Please return then.</div>':`<form id="publicReport" class="form-stack">${reportFields(data.report||{})}<button class="primary">${data.report?'Update report':'Submit report'}</button><p id="publicResult" role="status"></p></form>`}`;$('#publicReport')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const input=validateReport(Object.fromEntries(new FormData(e.target)));data.report=await call('PUT',{...input,revision:data.report?.revision||0});$('#publicResult').textContent='Thank you. Your report has been saved.'}catch(err){$('#publicResult').textContent=err.message+' If another organizer edited this report, reopen the original link before making changes.'}finally{button.disabled=false}})}draw();}catch(e){root.innerHTML='<h1>Report unavailable</h1><p>'+esc(e.message)+'</p>'}}
 async function importBackup(data){if(!cloud())return false;const result=await mutate('/api/import','POST',data);bridge.toast(result.message+' Custom poster attachments remain local.');return true}
 return{importBackup,persist,afterRender,render:v=>v==='teachers'?teachersView():v==='reports'?reportsView():v==='monthly'?monthlyView():null,start,cloud,flush};
}
